import {createContext, type PropsWithChildren, useContext, useMemo} from 'react'

export type SectionContext = {
  loading: boolean
  readOnly: boolean
  headingId?: string
}

export const SectionContext = createContext<SectionContext | undefined>(undefined)

export function SectionProvider({
  children,
  loading = false,
  readOnly = false,
  headingId,
}: PropsWithChildren<Partial<SectionContext>>) {
  const value = useMemo<SectionContext>(
    () => ({
      loading,
      readOnly,
      headingId,
    }),
    [loading, readOnly, headingId],
  )
  return <SectionContext.Provider value={value}>{children}</SectionContext.Provider>
}

export function useSection() {
  const context = useContext(SectionContext)
  if (!context) {
    throw new Error('useSection must be used within a SectionProvider')
  }
  return context
}

try{ SectionContext.displayName ||= 'SectionContext' } catch {}
try{ SectionProvider.displayName ||= 'SectionProvider' } catch {}